package gotable

import (
	"os"
	"strings"
	"testing"
)

// TestGoLegSizeCodecs pins the codecs group's size budget: its BASE line count
// is 2054 (codecs.go 1052, cook.go 847, cookwrite.go 155) and the budget is 5%
// under that, 1951. Contraction must never change a generated byte.
func TestGoLegSizeCodecs(t *testing.T) {
	t.Parallel()
	const baseLines, budget = 2054, 1951
	total := 0
	for _, name := range []string{"codecs.go", "cook.go", "cookwrite.go"} {
		src, err := os.ReadFile(name)
		if err != nil {
			t.Fatal(err)
		}
		total += strings.Count(string(src), "\n")
	}
	t.Logf("codecs group: %d lines, budget %d (BASE %d)", total, budget, baseLines)
	if total > budget {
		t.Fatalf("codecs group is %d lines, over budget %d (BASE %d, 5%% under)", total, budget, baseLines)
	}
}
